INSERT INTO public.maxims (
  id, latin_phrase, indonesian_meaning, literal_translation,
  pronunciation_guide, legal_fields, legal_meaning, history,
  is_active, status, difficulty, version_number, data,
  created_at, updated_at
) VALUES (
  'pacta-sunt-servanda',
  'Pacta Sunt Servanda',
  'Setiap perjanjian yang dibuat secara sah mengikat para pihak yang membuatnya dan harus dilaksanakan dengan itikad baik',
  'Perjanjian-perjanjian harus dipatuhi',
  '/ˈpæk.tɑː sʊnt sɜːrˈvæn.də/',
  ARRAY['perdata'],
  'Pacta Sunt Servanda adalah sebuah maksim hukum Latin yang berarti "perjanjian harus dipatuhi." Asas ini menegaskan bahwa setiap perjanjian yang telah dibuat secara sah oleh para pihak memiliki kekuatan mengikat dan wajib dilaksanakan sebagaimana mestinya. Tidak ada pihak yang dapat secara sepihak melepaskan diri dari kewajiban perjanjiannya tanpa alasan hukum yang sah atau persetujuan dari pihak lain.

Fungsi utama dari asas ini adalah menjamin kepastian hukum (legal certainty) dan stabilitas hubungan bisnis. Dalam dunia perdagangan dan interaksi sosial, individu dan entitas hukum perlu memiliki keyakinan bahwa janji yang diberikan akan ditepati. Tanpa asas ini, kepercayaan (trust) sebagai modal dasar transaksi akan runtuh, menyebabkan ketidakstabilan ekonomi dan sosial.

Ruang lingkup penerapan asas ini mencakup semua jenis perjanjian, baik yang diatur khusus dalam undang-undang (perjanjian bernama) maupun yang tidak diatur secara khusus (perjanjian tidak bernama), selama memenuhi syarat sahnya perjanjian menurut undang-undang. Asas ini juga menuntut pelaksanaan perjanjian dengan itikad baik (good faith), yang berarti para pihak tidak hanya terpaku pada teks harfiah, tetapi juga pada semangat dan tujuan awal perjanjian.',
  'Sejarah asas Pacta Sunt Servanda dapat ditelusuri melalui tahapan berikut:

Hukum Romawi Kuno: Dalam hukum Romawi awal, hanya perjanjian formal tertentu (contractus) yang memiliki kekuatan mengikat. Perjanjian informal (pacta nuda) umumnya tidak dapat dituntut di pengadilan (ex nudo pacto non oritur actio). Namun seiring perkembangan zaman, praetor mulai memberikan perlindungan hukum terhadap beberapa jenis perjanjian informal berdasarkan asas keadilan dan itikad baik.

Abad Pertengahan dan Hukum Kanonik: Gereja Katolik melalui Hukum Kanonik memainkan peran penting dalam memperkuat asas ini. Gereja mengajarkan bahwa mengingkari janji adalah dosa (sin of perjury). Oleh karena itu, pacta sunt servanda diangkat menjadi prinsip moral universal yang melampaui bentuk formalitas hukum sipil.

Era Kodifikasi (Abad ke-19): Ketika negara-negara Eropa mulai mengkodifikasi hukum perdatanya, asas ini diadopsi secara penuh. Code Napoléon (1804) Pasal 1134 menyatakan: "Agreements legally formed have the force of law for those who make them." Belanda mengadopsi prinsip ini dalam Burgerlijk Wetboek (BW) 1838, yang kemudian menjadi dasar KUHPerdata di Indonesia.

Indonesia (Masa Kolonial hingga Kini): Sejak diberlakukannya KUHPerdata di Hindia Belanda, asas ini menjadi fondasi hukum perikatan di Indonesia. KUHPerdata warisan kolonial ini masih berlaku penuh berdasarkan aturan peralihan UUD 1945, sehingga Pacta Sunt Servanda tetap menjadi asas hidup yang sangat relevan dalam praktik hukum bisnis dan perdata di Indonesia saat ini.',
  true,
  'stable',
  'dasar',
  1,
  '{"synonyms":["Asas Kekekalan Perjanjian","Asas Mengikatnya Perjanjian"],"usedIn":["Indonesia","Belanda","Prancis","Jerman","hampir seluruh negara di dunia"],"classification":{"legalBranch":"Hukum Perdata Materiil, khususnya Hukum Perikatan dan Hukum Kontrak","nature":"Imperatif","applicationLevel":"Nasional dan Internasional","traditionSource":"Hukum Romawi Kuno, dikembangkan oleh para ahli hukum abad pertengahan, diadopsi dalam Code Napoléon dan KUHPerdata Belanda/Indonesia"},"applicabilityStatus":{"validInIndonesia":true,"validInternationally":true,"recognizedByDoctrine":true,"codified":true,"notes":"Dikodifikasi dalam Pasal 1338 ayat (1) KUHPerdata dan Konvensi Wina 1969 Pasal 26"},"wordByWord":[{"word":"Pacta","meaning":"Perjanjian, kesepakatan, janji (jamak)"},{"word":"Sunt","meaning":"Adalah, merupakan"},{"word":"Servanda","meaning":"Harus dipatuhi, harus dilayani, harus dijaga"}],"wordByWordExtended":[{"word":"Pacta","latinForm":"Pactum, -i (n)","partOfSpeech":"Nomina (Jamak, Netral)","meaning":"Perjanjian, kesepakatan, janji"},{"word":"Sunt","latinForm":"Esse (verba)","partOfSpeech":"Verba (Indikatif Aktif, Orang ke-3 Jamak)","meaning":"Adalah, merupakan"},{"word":"Servanda","latinForm":"Servare (verba)","partOfSpeech":"Gerundivum (Jamak, Netral)","meaning":"Harus dipatuhi, harus dilayani, harus dijaga"}],"etymologyNotes":"Frasa ini menggunakan konstruksi Gerundivum yang menyatakan keharusan atau kewajiban pasif. Pacta adalah subjek jamak (\"perjanjian-perjanjian\"). Sunt adalah kata kerja penghubung (\"adalah\"). Servanda adalah bentuk gerundivum dari servare yang menyatakan kewajiban (\"yang harus dipatuhi\"). Secara harfiah: \"Perjanjian-perjanjian adalah hal-hal yang harus dipatuhi.\"","philosophicalMeaning":{"origin":"Asas ini berakar pada filosofi moral dan etika kontrak yang menjunjung tinggi otonomi kehendak (autonomy of will) dan integritas pribadi. Ketika seseorang secara sukarela mengikatkan diri dalam perjanjian, ia telah menggunakan kebebasannya tersebut.","justiceValue":"Keadilan dalam kontrak bukan hanya tentang hasil akhir, tetapi tentang proses menepati janji. Seseorang yang telah menerima manfaat dari perjanjian wajib memberikan imbalan atau kinerja yang telah dijanjikan.","romanThought":"Dalam hukum Romawi, praetor mulai memberikan perlindungan hukum terhadap perjanjian informal berdasarkan asas keadilan dan itikad baik, mengembangkan konsep awal pacta sunt servanda dari formalitas menuju substansi.","modernRelevance":"Relevansi modernnya terletak pada pondasi kepercayaan dalam transaksi bisnis global. Tanpa asas ini, kepercayaan sebagai modal dasar transaksi akan runtuh dan menyebabkan ketidakstabilan ekonomi."},"historyTimeline":[{"era":"Hukum Romawi Kuno","period":"Romawi Kuno","description":"Hanya perjanjian formal (contractus) yang mengikat. Perjanjian informal (pacta nuda) tidak dapat dituntut. Seiring waktu praetor mulai memberikan perlindungan berdasarkan itikad baik."},{"era":"Abad Pertengahan","period":"Abad ke-5–15","description":"Gereja Katolik melalui Hukum Kanonik mengajarkan bahwa mengingkari janji adalah dosa. Pacta sunt servanda diangkat menjadi prinsip moral universal melampaui formalitas hukum sipil."},{"era":"Era Kodifikasi","period":"Abad ke-19","description":"Code Napoléon (1804) Pasal 1134 mengadopsi asas ini. Belanda melalui BW 1838 turut mengkodifikasikannya, yang menjadi dasar KUHPerdata Indonesia."},{"era":"Indonesia Pasca Kemerdekaan","period":"Modern","description":"KUHPerdata warisan kolonial masih berlaku penuh. Pasal 1338 ayat (1) KUHPerdata menjadi fondasi hukum perikatan dan kontrak di Indonesia hingga saat ini."}],"doctrineDevelopment":[{"era":"Doktrin Formalistik Klasik","description":"Penekanan hanya pada kepatuhan terhadap teks tertulis perjanjian. Apa yang tertulis harus dilakukan, terlepas dari perubahan keadaan."},{"era":"Doktrin Itikad Baik","description":"Perkembangan modern menambahkan lapisan penafsiran bahwa pelaksanaan perjanjian harus disertai itikad baik. Para pihak harus bertindak jujur dan memperhatikan kepentingan pihak lain."},{"era":"Doktrin Rebus Sic Stantibus","description":"Sebagai penyeimbang, muncul doktrin bahwa perjanjian mengikat selama keadaan masih sama. Jika terjadi perubahan keadaan mendasar dan tidak terduga, kekekalan perjanjian dapat ditinjau ulang."},{"era":"Doktrin Penyalahgunaan Hak","description":"Pelaksanaan hak berdasarkan perjanjian tidak boleh dilakukan semata-mata untuk merugikan pihak lain atau menyimpang dari tujuan pemberian hak tersebut."}],"elements":["Adanya Kesepakatan Para Pihak (Consensus): Terdapat kata sepakat antara pihak yang mengikatkan diri.","Kecakapan Untuk Membuat Perjanjian: Para pihak harus cakap menurut hukum (dewasa dan tidak di bawah pengampuan).","Hal Tertentu: Objek perjanjian harus jelas dan tertentu.","Sebab yang Halal: Tujuan atau causa dari perjanjian tidak boleh bertentangan dengan undang-undang, ketertiban umum, atau kesusilaan."],"conditions":["Perjanjian Harus Sah Secara Hukum: Memenuhi 4 syarat Pasal 1320 KUHPerdata. Jika tidak, perjanjian dapat dibatalkan atau batal demi hukum.","Tidak Ada Alasan Pembebasan yang Sah: Tidak terjadi force majeure atau keadaan memaksa yang membuat pelaksanaan perjanjian mustahil.","Dilaksanakan Dengan Itikad Baik: Para pihak melaksanakan kewajiban sesuai dengan semangat perjanjian, bukan hanya teks harfiah."],"exceptions":["Force Majeure (Keadaan Memaksa): Peristiwa yang tidak dapat diduga dan tidak dapat dicegah (bencana alam, perang, perubahan regulasi drastis) yang membuat pelaksanaan perjanjian mustahil.","Persetujuan Bersama Untuk Mengakhiri: Para pihak dapat sepakat bersama-sama untuk membatalkan atau mengubah perjanjian (novasi atau pembatalan konsensual).","Putusan Pengadilan: Jika perjanjian terbukti mengandung unsur cacat kehendak (penipuan, kekeliruan, paksaan) atau sebab yang haram, pengadilan dapat membatalkannya.","Dalil Rebus Sic Stantibus: Jika terjadi perubahan keadaan yang sangat mendasar sehingga pelaksanaan perjanjian akan menimbulkan ketidakadilan ekstrem, pengadilan dapat menyesuaikan atau mengakhiri perjanjian."],"scope":{"applies":["Semua perjanjian perdata yang sah (jual beli, sewa menyewa, hutang piutang, jasa, dll).","Perjanjian kerja antara pengusaha dan pekerja (dengan batasan peraturan ketenagakerjaan).","Perjanjian internasional antar negara (traktat).","Perjanjian baku (standard contract) selama klausulnya tidak bertentangan dengan ketentuan wajib undang-undang."],"doesNotApply":["Perjanjian yang cacat formil atau materiil (tidak memenuhi Pasal 1320 KUHPerdata).","Klausul kontrak yang dilarang oleh undang-undang (misalnya klausul pembebasan tanggung jawab atas kelalaian berat).","Hubungan hukum yang didasarkan pada undang-undang secara langsung, bukan kesepakatan."]},"legalBasisTable":[{"statute":"KUHPerdata (BW)","article":"Pasal 1338 ayat (1)","relevance":"\"Semua perjanjian yang dibuat secara sah berlaku sebagai undang-undang bagi mereka yang membuatnya.\" Rumusan positif dari Pacta Sunt Servanda."},{"statute":"KUHPerdata (BW)","article":"Pasal 1338 ayat (3)","relevance":"\"Perjanjian-perjanjian harus dilaksanakan dengan itikad baik.\" Melengkapi asas kekekalan dengan asas kejujuran."},{"statute":"KUHPerdata (BW)","article":"Pasal 1320","relevance":"Syarat sahnya perjanjian. Tanpa pemenuhan pasal ini, asas Pacta Sunt Servanda tidak timbul."},{"statute":"KUHPerdata (BW)","article":"Pasal 1266","relevance":"Mengatur pembatalan perjanjian melalui putusan hakim jika salah satu pihak tidak memenuhi kewajibannya."},{"statute":"Konvensi Wina 1969","article":"Pasal 26","relevance":"\"Every treaty in force is binding upon the parties to it and must be performed by them in good faith.\" — dasar internasional asas ini."}],"indonesianLegalBasis":"Pasal 1338 ayat (1) dan (3) Kitab Undang-Undang Hukum Perdata (KUHPerdata).","indonesianSystemRelation":"Bagi Hakim: tidak boleh mengubah isi perjanjian yang sah hanya karena salah satu pihak merasa rugi, kecuali ada pelanggaran itikad baik, force majeure, atau cacat kehendak. Bagi Legislator: menghormati kebebasan berkontrak sambil menjaga ketentuan wajib untuk perlindungan pihak lemah. Bagi Akademisi: mengkaji batas-batas kebebasan berkontrak vs. perlindungan konsumen dan pihak yang lemah.","normativeExamples":["Perjanjian Jual Beli Tanah: Dalam akta jual beli tanah yang dibuat di hadapan Notaris, pembeli wajib membayar harga dan penjual wajib menyerahkan sertifikat. Penjual tidak bisa menaikkan harga setelah akad ditandatangani.","Perjanjian Kredit Bank: Debitur yang menandatangani perjanjian kredit wajib membayar angsuran sesuai jadwal. Bank tidak bisa sepihak menaikkan bunga jika dalam kontrak ditetapkan bunga tetap.","Perjanjian Kerja Waktu Tertentu (PKWT): Pekerja dan pemberi kerja terikat pada jangka waktu yang disepakati. Pemberi kerja tidak bisa memecat pekerja sebelum waktu habis tanpa alasan sah menurut UU Ketenagakerjaan."],"practicalExamples":["Sengketa Konstruksi: Perusahaan konstruksi setuju membangun gedung dengan harga Rp10 Miliar dalam 1 tahun. Di tengah jalan, harga bahan bangunan naik drastis. Perusahaan tetap wajib menyelesaikan proyek kecuali kenaikan harga tersebut disebabkan force majeure yang diatur dalam kontrak.","Penyewaan Ruko: Penyewa setuju membayar sewa Rp50 juta per tahun selama 5 tahun. Di tahun ke-3, nilai pasar sewa naik menjadi Rp80 juta. Pemilik ruko tidak bisa mengusir penyewa atau menaikkan sewa secara sepihak. Perjanjian lama tetap mengikat.","Pengiriman Barang Ekspor-Impor: Eksportir Indonesia dan Importir Jepang menandatangani kontrak pengiriman kopi. Jika eksportir mengirim barang kualitas rendah, ia telah melanggar Pacta Sunt Servanda dan wajib mengganti rugi atau mengirim ulang barang yang sesuai."],"jurisprudence":[{"id":"ma-210-2011","courtName":"Mahkamah Agung","caseNumber":"No. 210 K/Pdt/2011","year":2011,"date":"2011","context":"Sengketa Wanprestasi Perjanjian Jual Beli","excerpt":"MA menegaskan bahwa perjanjian yang dibuat secara sah mengikat para pihak seperti undang-undang. Hakim tidak dapat mengubah syarat-syarat perjanjian yang telah disepakati hanya karena salah satu pihak merasa dirugikan.","summary":"Penerapan murni Pasal 1338 ayat (1) KUHPerdata. Hakim menghormati otonomi kehendak para pihak.","analysis":"Putusan ini menegaskan bahwa Pacta Sunt Servanda bersifat mutlak selama perjanjian dibuat secara sah dan tidak ada force majeure atau cacat kehendak.","sourceUrl":"https://www.mahkamahagung.go.id"},{"id":"ma-490-2012","courtName":"Mahkamah Agung","caseNumber":"No. 490 K/Pdt/2012","year":2012,"date":"2012","context":"Pembatalan Perjanjian Karena Cacat Kehendak","excerpt":"MA menyatakan bahwa meskipun asas Pacta Sunt Servanda berlaku, perjanjian dapat dibatalkan jika terbukti adanya unsur penipuan (bedrog) yang merupakan cacat kehendak menurut Pasal 1321 KUHPerdata.","summary":"Menunjukkan batas dari Pacta Sunt Servanda: asas ini hanya berlaku untuk perjanjian yang \"sah\" dan bebas dari cacat.","analysis":"Batasan penting: asas kekekalan perjanjian tidak melindungi kontrak yang lahir dari penipuan atau paksaan.","sourceUrl":"https://www.mahkamahagung.go.id"},{"id":"pn-450-2019","courtName":"Pengadilan Negeri Jakarta Pusat","caseNumber":"No. 450/Pdt.G/2019/PN.Jkt.Pst","year":2019,"date":"2019","context":"Sengketa Perjanjian Kerjasama Bisnis","excerpt":"PN memutuskan bahwa tergugat wajib melaksanakan kewajibannya sesuai kontrak karena tidak ada bukti force majeure. Tergugat berdalih kondisi ekonomi sulit, namun dalih tersebut tidak menggugurkan kewajiban kontrak.","summary":"Menegaskan bahwa kesulitan ekonomi biasa bukan alasan untuk melepaskan diri dari Pacta Sunt Servanda.","analysis":"Perbedaan penting antara hardship (kesulitan ekonomi) yang tidak membebaskan, dengan force majeure sejati yang membebaskan kewajiban.","sourceUrl":"https://www.mahkamahagung.go.id"}],"caseExamples":[],"internationalComparisons":[{"country":"Belanda","status":"Dikenal","description":"Pasal 6:248 BW Belanda sangat mirip dengan Indonesia, menekankan itikad baik. Hukum Belanda lebih terbuka terhadap penyesuaian kontrak (herziening van de overeenkomst) jika terjadi keadaan yang tidak terduga."},{"country":"Jerman","status":"Dikenal","description":"BGB § 242 tentang Treu und Glauben (Itikad Baik). Jerman juga memiliki doktrin Störung der Geschäftsgrundlage (gangguan dasar transaksi) yang memungkinkan penyesuaian kontrak jika asumsi dasar para pihak berubah drastis."},{"country":"Prancis","status":"Dikenal","description":"Code Civil Prancis Pasal 1103 (revisi 2016) menyatakan: \"Contracts legally formed bind those who have made them.\" Reformasi hukum obligasi 2016 memperkenalkan fleksibilitas untuk imprévision."},{"country":"Inggris","status":"Dikenal","description":"Inggris sangat ketat pada Pacta Sunt Servanda. Doktrin frustration of contract sangat sempit. Inggris umumnya tidak mengakui hardship sebagai alasan pembebasan."},{"country":"Amerika Serikat","status":"Dikenal","description":"UCC dan Restatement of Contracts mengakui impracticability dan frustration of purpose sebagai pengecualian, namun standar pembuktiannya sangat tinggi."}],"maximComparisons":[{"maximId":"rebus-sic-stantibus","latinPhrase":"Rebus Sic Stantibus","whenUsed":"Merupakan pengecualian atau penyeimbang. Jika keadaan berubah drastis, Pacta Sunt Servanda bisa ditinjau ulang."},{"maximId":"consensus-ad-idem","latinPhrase":"Consensus Ad Idem","whenUsed":"Merupakan prasyarat. Tanpa consensus, tidak ada pacta yang bisa di-servanda."},{"maximId":"good-faith","latinPhrase":"Good Faith (Bona Fide)","whenUsed":"Merupakan cara pelaksanaan. Pacta Sunt Servanda bukan hanya soal teks, tapi soal semangat itikad baik (Pasal 1338 ayat 3 KUHPerdata)."}],"analysis":{"purpose":"Menciptakan stabilitas transaksi dan melindungi harapan yang wajar (legitimate expectations) para pihak.","protectedValues":"Kepastian hukum, kepercayaan, dan otonomi individu.","advantages":"Memberikan kejelasan hak dan kewajiban, mengurangi potensi sengketa, dan mendorong efisiensi ekonomi.","critique":"Dapat menjadi terlalu kaku dan menimbulkan ketidakadilan jika terjadi perubahan keadaan yang ekstrem (hardship) yang tidak diantisipasi para pihak. Asas ini bisa menjadi alat penindasan bagi pihak yang lemah jika kontrak baku dibuat secara sepihak oleh korporasi besar.","limitations":"Bergantung pada kemampuan para pihak merumuskan kontrak dengan baik. Bagi pihak yang lemah (konsumen), Pacta Sunt Servanda bisa disalahgunakan jika tidak ada pengawasan terhadap klausula baku."},"scholarViews":[{"name":"Prof. Subekti, S.H.","view":"Pasal 1338 KUHPerdata adalah manifestasi dari asas Pacta Sunt Servanda. Hakim tidak boleh bertindak sebagai \"pembuat kontrak baru\" dengan mengubah isi perjanjian yang sudah jelas, kecuali ada alasan hukum yang kuat seperti wanprestasi atau cacat kehendak.","source":"Hukum Perikatan (2002)"},{"name":"Prof. Mariam Darus Badrulzaman, S.H.","view":"Asas ini tidak berdiri sendiri, melainkan berjalan beriringan dengan asas itikad baik. Pelaksanaan perjanjian yang kaku tanpa memperhatikan itikad baik dapat dianggap sebagai penyalahgunaan hak.","source":"Hukum Perikatan Nasional (2004)"},{"name":"Prof. R. Setiawan, S.H.","view":"Kekuatan mengikat perjanjian seperti undang-undang ini bersifat relatif (inter partes), artinya hanya mengikat para pihak yang membuat perjanjian, bukan pihak ketiga.","source":"Pokok-Pokok Hukum Perikatan (1999)"}],"controversies":[{"title":"Ketegangan antara Kepastian Kontrak dan Keadilan Substansial","description":"Pihak yang lebih kuat (korporasi) seringkali memanfaatkan asas ini untuk memaksakan klausul-klausul yang merugikan pihak lemah (konsumen atau mitra kecil) dengan dalih \"itu sudah tertuang dalam kontrak\". Penerapan Pacta Sunt Servanda yang terlalu kaku tanpa pengawasan terhadap klausula baku dapat bertentangan dengan asas keadilan dan perlindungan konsumen."}],"commonMistakes":[{"misconception":"\"Kontrak adalah hukum mutlak yang tidak bisa diganggu gugat.\"","fact":"Salah. Kontrak bisa dibatalkan jika ada cacat kehendak, sebab haram, atau melalui putusan pengadilan jika terjadi wanprestasi."},{"misconception":"\"Saya bisa membatalkan kontrak sepihak jika saya rugi.\"","fact":"Salah. Kerugian bisnis adalah risiko yang harus ditanggung. Pembatalan sepihak tanpa alasan sah adalah wanprestasi."},{"misconception":"\"Pacta Sunt Servanda berarti teks kontrak adalah segalanya.\"","fact":"Tidak sepenuhnya. Pasal 1338 ayat (3) mewajibkan itikad baik, yang berarti semangat dan tujuan kontrak juga penting, bukan hanya huruf-hurufnya."},{"misconception":"\"Asas ini hanya berlaku untuk kontrak tertulis.\"","fact":"Salah. Perjanjian lisan pun mengikat jika memenuhi syarat sah perjanjian, meskipun lebih sulit pembuktiannya."}],"faq":[{"question":"Apakah Pacta Sunt Servanda berlaku untuk perjanjian lisan?","answer":"Ya, selama perjanjian tersebut memenuhi syarat sah perjanjian (Pasal 1320 KUHPerdata). Namun, pembuktiannya lebih sulit dibandingkan perjanjian tertulis."},{"question":"Bagaimana jika salah satu pihak merasa kontraknya tidak adil?","answer":"Ketidakadilan subjektif tidak membatalkan kontrak. Kecuali jika disebabkan oleh penipuan, paksaan, atau kekeliruan (cacat kehendak), atau klausulnya bertentangan dengan ketentuan wajib undang-undang."},{"question":"Apakah inflasi atau krisis ekonomi bisa membatalkan Pacta Sunt Servanda?","answer":"Umumnya tidak. Risiko ekonomi adalah bagian dari bisnis. Kecuali jika krisis mencapai tingkat force majeure yang membuat pelaksanaan mustahil secara fisik atau hukum, atau jika para pihak menyepakati klausul penyesuaian harga."},{"question":"Apa bedanya Pacta Sunt Servanda dengan Force Majeure?","answer":"Pacta Sunt Servanda adalah aturan umum bahwa kontrak harus dijalankan. Force Majeure adalah pengecualian spesifik yang membebaskan pihak dari kewajiban tersebut karena kejadian di luar kendali."},{"question":"Bisakah hakim mengubah isi kontrak?","answer":"Pada prinsipnya, tidak. Hakim hanya menegakkan kontrak. Namun dalam praktik tertentu, jika ada unsur itikad buruk atau ketidakseimbangan kekuasaan yang ekstrem, hakim dapat menafsirkan ulang atau membatalkan klausul tertentu yang bertentangan dengan hukum."}],"maximNotes":"Penting untuk membedakan antara kekuatan mengikat (binding force) dan pelaksanaan (performance). Pacta Sunt Servanda menjamin kekuatan mengikat. Pelaksanaan yang buruk disebut wanprestasi. Dalam kontrak internasional, seringkali dipilih hukum mana yang berlaku (choice of law). Jika dipilih hukum Indonesia, maka Pacta Sunt Servanda versi KUHPerdata yang berlaku.","relatedTerms":[{"term":"Wanprestasi","definition":"Cidera janji — kegagalan memenuhi kewajiban yang telah diperjanjikan."},{"term":"Force Majeure","definition":"Keadaan memaksa — peristiwa di luar kendali yang membuat pelaksanaan perjanjian mustahil."},{"term":"Itikad Baik","definition":"Good Faith — kejujuran dan keadilan dalam melaksanakan perjanjian."},{"term":"Cacat Kehendak","definition":"Defect of Will — ketidaksempurnaan dalam pembentukan kehendak (penipuan, paksaan, kekeliruan)."},{"term":"Novasi","definition":"Pembaharuan utang — penggantian perikatan lama dengan perikatan baru."},{"term":"Kompensasi","definition":"Set-off — perjumpaan hutang antara dua pihak yang saling berutang."},{"term":"Pembebasan Utang","definition":"Release of Debt — pelepasan kewajiban oleh kreditur secara sukarela."},{"term":"Klausula Baku","definition":"Standard Clause — klausul yang disiapkan sepihak oleh pihak yang lebih kuat."},{"term":"Restitusi","definition":"Pengembalian ke keadaan semula jika perjanjian dibatalkan."},{"term":"Inter Partes","definition":"Di antara para pihak — kekuatan mengikat perjanjian hanya berlaku bagi pihak yang membuatnya."}],"relations":[{"id":"rebus-sic-stantibus","latinPhrase":"Rebus Sic Stantibus","indonesianMeaning":"Selama keadaan masih sama","relationType":"berlawanan"},{"id":"consensus-ad-idem","latinPhrase":"Consensus Ad Idem","indonesianMeaning":"Kesepakatan para pihak","relationType":"hierarkis"},{"id":"good-faith-bona-fide","latinPhrase":"Good Faith (Bona Fide)","indonesianMeaning":"Itikad baik","relationType":"terkait"}],"references":{"primary":{"statutes":["Kitab Undang-Undang Hukum Perdata (Burgerlijk Wetboek), Pasal 1320, 1338, 1266.","Konvensi Wina tentang Hukum Perjanjian 1969 (Vienna Convention on the Law of Treaties), Pasal 26."]},"secondary":{"books":["Subekti. (2002). Hukum Perikatan. Jakarta: Pradnya Paramita.","Mariam Darus Badrulzaman. (2004). Hukum Perikatan Nasional. Bandung: Alumni.","Setiawan, R. (1999). Pokok-Pokok Hukum Perikatan. Bandung: Alumni.","Abdulkadir Muhammad. (2010). Hukum Kontrak Indonesia. Bandung: Citra Aditya Bakti.","Satrio Efendi, J. Hukum Kontrak Indonesia.","Widjaja, Gunawan dan Andi Laksana. Serba-Serbi Perikatan."],"journals":["Jurnal Hukum Bisnis. Artikel mengenai \"Penerapan Asas Pacta Sunt Servanda dalam Sengketa Bisnis Modern\".","Jurnal Mimbar Hukum. Analisis kritis tentang batas-batas kebebasan berkontrak."]},"tertiary":{"encyclopedias":["Mahkamah Agung Republik Indonesia. Direktori Putusan.","Badan Pembinaan Hukum Nasional (BPHN). Kompilasi Hukum Perdata."]}},"furtherReading":[{"title":"Hukum Perikatan","author":"Subekti","type":"buku"},{"title":"Hukum Kontrak Indonesia","author":"Abdulkadir Muhammad","type":"buku"},{"title":"Pokok-Pokok Hukum Perikatan","author":"R. Setiawan","type":"buku"},{"title":"Jurnal Hukum Bisnis","author":"Berbagai Penulis","type":"jurnal"},{"title":"Jurnal Mimbar Hukum","author":"Berbagai Penulis","type":"jurnal"}],"meta":{"categories":["Asas Hukum","Hukum Perdata","Hukum Kontrak"],"portals":["Ilmu Hukum","Bisnis dan Perdagangan"],"tags":["Pacta Sunt Servanda","Pasal 1338 KUHPerdata","Kekekalan Perjanjian","Itikad Baik","Wanprestasi","Force Majeure"]}}'::jsonb,
  now(),
  now()
)
